// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Run any catalog job: turn a job row into flow steps and send it through the safety ladder
// Flo: check needed args > resolve the page > map label keys to names (packs, owner overrides) > skip empty optional typing > once-only key > execWrite; list jobs loop item by item
// I/O: Job row + Args (caller) > count of items done; errors BadUsage NoElement CapHit NeedApprove ...
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const flow = @import("ru-flow-runz.zig"); const jobs = @import("ru-jobs-tabl.zig"); const pack = @import("ut-loca-pack.zig"); const post = @import("ru-post-main.zig");
const CF = .{ .dayz = 86400000, .snip = 30 };
pub fn argOf(args: task.Args, arg: jobs.Arg) []const u8 { return switch (arg) { .none => "", .text => args.text, .to => args.to, .url => args.url, .title => args.title, .price => args.price, .desc => args.desc, .group => args.group, .photo => args.photo, .opt => args.opt, .date => args.date, .time => args.time }; }
pub fn pathOf(ctx: *task.Ctx, args: task.Args, src: jobs.Src) ![]const u8 { const cf = ctx.conf; return switch (src) { .none => "", .url => args.url, .home => cf.path_home_main, .noti => cf.path_noti_comm, .frie_requ => cf.path_frie_requ, .birt => cf.path_birt_main, .msgr => cf.path_msgr_main, .msgr_requ => cf.path_msgr_requ, .mark_sell => cf.path_mark_sell, .evnt_crea => cf.path_evnt_crea, .stor_crea => cf.path_stor_crea, .reel_crea => cf.path_reel_crea, .prof => cf.path_prof_main, .bizz => try std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ cf.base_bizz_main, cf.path_bizz_crea }), .dmsg_thre => try std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ cf.path_dmsg_thre, args.to }) }; }
fn labsFor(ctx: *task.Ctx, args: task.Args, tpl: jobs.T) ![]const []const u8 { if (tpl.larg != .none) { const val = argOf(args, tpl.larg); if (val.len > 0) { const one = try ctx.aren.alloc([]const u8, 1); one[0] = val; return one; } } if (tpl.key.len > 0) return pack.lab(ctx.conf, tpl.key); if (tpl.op == .expect and tpl.arg != .none) { const one = try ctx.aren.alloc([]const u8, 1); one[0] = post.cutUtf8(argOf(args, tpl.arg), CF.snip); return one; } return &.{}; }
pub fn build(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args, path: []const u8, idx: usize) ![]flow.Step { var out: std.ArrayList(flow.Step) = .empty; for (job.steps) |tpl| { const val = argOf(args, tpl.arg); const optional = (tpl.op == .typez or tpl.op == .upload or tpl.op == .select or tpl.op == .clear) and tpl.arg != .none; if (optional and val.len == 0) continue; if (tpl.op == .expect and val.len == 0) continue; const txt = switch (tpl.op) { .goto => path, .key => tpl.lit, .typez, .upload, .select => val, else => "" }; try out.append(ctx.aren, .{ .op = tpl.op, .role = tpl.role, .labs = try labsFor(ctx, args, tpl), .text = txt, .nth = if (tpl.idx) idx else 0, .commit = tpl.commit }); } return out.items; }
fn argHash(ctx: *task.Ctx, args: task.Args, path: []const u8) ![]u8 { const all = try std.fmt.allocPrint(ctx.aren, "{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}", .{ path, args.text, args.to, args.title, args.price, args.desc, args.group, args.photo, args.opt, args.date, args.time, args.url }); return task.hashHex(ctx, all); }
fn needOk(job: *const jobs.Job, args: task.Args) bool { for (job.need) |nd| { if (argOf(args, nd).len == 0) return false; } return true; }
fn firstLabeled(job: *const jobs.Job) ?jobs.T { for (job.steps) |tpl| { if (tpl.key.len > 0 and (tpl.op == .click or tpl.op == .typez)) return tpl; } return null; }
pub fn runOne(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args) !task.Out { if (!needOk(job, args)) return error.BadUsage; const path = try pathOf(ctx, args, job.src); const hsh = try argHash(ctx, args, path); const key = try std.fmt.allocPrint(ctx.aren, "job|{s}|{s}", .{ job.name, hsh }); const what = try std.fmt.allocPrint(ctx.aren, "{s} at {s}", .{ job.name, path }); const stps = try build(ctx, job, args, path, 0); return task.execWrite(ctx, job.kind, key, what, job.risk == .x, stps); }
pub fn runEach(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args) !u32 { if (!needOk(job, args)) return error.BadUsage; const path = try pathOf(ctx, args, job.src); try task.visit(ctx, path); const lead = firstLabeled(job) orelse return error.BadUsage; ctx.page.arm(ctx.conf.brow_time_seco * 1000); const avail = try ctx.page.axCount(ctx.aren, if (lead.role.len > 0) lead.role else if (lead.op == .typez) "textbox" else "button", pack.lab(ctx.conf, lead.key)); const hsh = try argHash(ctx, args, path); const day = @divFloor(task.nowMs(ctx), CF.dayz); var did: u32 = 0; var idx: usize = 0; while (idx < @min(avail, args.maxn)) : (idx += 1) { const key = try std.fmt.allocPrint(ctx.aren, "each|{s}|{d}|{d}|{s}", .{ job.name, idx, day, hsh }); const what = try std.fmt.allocPrint(ctx.aren, "{s} item {d} at {s}", .{ job.name, idx + 1, path }); const stps = try build(ctx, job, args, path, idx); const out = task.execWrite(ctx, job.kind, key, what, job.risk == .x, stps) catch |err| { if (err == error.NoElement or err == error.Drift or err == error.Dupe) { task.say(ctx, "skipped item {d} ({s})", .{ idx + 1, @errorName(err) }); continue; } return err; }; if (out != .dupe) did += 1; } if (avail == 0) task.say(ctx, "nothing to do on that page", .{}); return did; }
pub fn run(ctx: *task.Ctx, job: *const jobs.Job, args: task.Args) !u32 { if (job.each) return runEach(ctx, job, args); const out = try runOne(ctx, job, args); return if (out == .dupe) 0 else 1; }
